//! Host-provided meeting notes, citations and task delivery.
use crate::primitives::brand_mark::brand_mark;
use crate::primitives::{
    clipboard,
    family::{Paint, PhaseClock, Slide, Tone, ease, face},
    glyph::{Glyph, icon, transformed},
    nav::tr,
};
use gpui::{prelude::*, *};
use std::{cell::Cell, collections::HashMap, rc::Rc};

#[derive(Clone)]
pub struct MeetingQuote {
    pub speaker: SharedString,
    pub time: SharedString,
    pub text: SharedString,
}
impl MeetingQuote {
    pub fn new(
        speaker: impl Into<SharedString>,
        time: impl Into<SharedString>,
        text: impl Into<SharedString>,
    ) -> Self {
        Self {
            speaker: speaker.into(),
            time: time.into(),
            text: text.into(),
        }
    }
}
#[derive(Clone)]
pub struct MeetingPoint {
    pub id: SharedString,
    pub text: SharedString,
    pub quote: Option<MeetingQuote>,
}
impl MeetingPoint {
    pub fn new(id: impl Into<SharedString>, text: impl Into<SharedString>) -> Self {
        Self {
            id: id.into(),
            text: text.into(),
            quote: None,
        }
    }
    pub fn quote(mut self, quote: MeetingQuote) -> Self {
        self.quote = Some(quote);
        self
    }
}
#[derive(Clone)]
pub struct MeetingAction {
    pub point: MeetingPoint,
    pub owner: SharedString,
    pub due: SharedString,
    pub done: bool,
}
impl MeetingAction {
    pub fn new(point: MeetingPoint, owner: impl Into<SharedString>) -> Self {
        Self {
            point,
            owner: owner.into(),
            due: "".into(),
            done: false,
        }
    }
}
#[derive(Clone)]
pub struct MeetingData {
    pub title: SharedString,
    pub meta: SharedString,
    pub attendees: Vec<SharedString>,
    pub summary: Vec<MeetingPoint>,
    pub decisions: Vec<MeetingPoint>,
    pub actions: Vec<MeetingAction>,
}
impl MeetingData {
    pub fn new(title: impl Into<SharedString>) -> Self {
        Self {
            title: title.into(),
            meta: "".into(),
            attendees: Vec::new(),
            summary: Vec::new(),
            decisions: Vec::new(),
            actions: Vec::new(),
        }
    }
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MeetingStatus {
    Summarizing,
    Ready,
    Error,
    NoTranscript,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MeetingSummaryEvent {
    ActionChanged {
        id: SharedString,
        done: bool,
    },
    Send {
        ticket: u64,
        id: SharedString,
        target: SharedString,
    },
    Cancel(u64),
    Regenerate,
    CopyResult(bool),
}
#[derive(Clone)]
enum SendState {
    Pending(u64),
    Sent(SharedString),
    Failed(SharedString),
}
pub struct MeetingSummary {
    service: SharedString,
    data: MeetingData,
    status: MeetingStatus,
    error: SharedString,
    send_states: HashMap<(SharedString, SharedString), SendState>,
    targets: Vec<SharedString>,
    ticket: u64,
    quote: Option<SharedString>,
    copying: bool,
    copied: Option<bool>,
    credit: SharedString,
    transcript_words: Option<usize>,
    reveal: PhaseClock,
    loading: PhaseClock,
    measured_body: Rc<Cell<Pixels>>,
    body_height: Slide,
}
impl EventEmitter<MeetingSummaryEvent> for MeetingSummary {}
impl MeetingSummary {
    /// Names the meeting service to display its mark.
    pub fn service(mut self, service: impl Into<SharedString>) -> Self {
        self.service = service.into();
        self
    }

    pub fn new(data: MeetingData) -> Self {
        Self {
            service: "".into(),
            data,
            status: MeetingStatus::Ready,
            error: "".into(),
            send_states: HashMap::new(),
            targets: vec!["Linear".into(), "Notion".into()],
            ticket: 0,
            quote: None,
            copying: false,
            copied: None,
            credit: "".into(),
            transcript_words: None,
            reveal: PhaseClock::default(),
            loading: PhaseClock::default(),
            measured_body: Rc::default(),
            body_height: Slide::new(0.),
        }
    }
    pub fn targets(mut self, targets: Vec<SharedString>) -> Self {
        self.targets = targets;
        self
    }
    pub fn with_transcript(mut self, credit: impl Into<SharedString>, words: usize) -> Self {
        self.credit = credit.into();
        self.transcript_words = Some(words);
        self
    }
    pub fn set_data(&mut self, data: MeetingData, cx: &mut Context<Self>) {
        for state in self.send_states.values() {
            if let SendState::Pending(ticket) = state {
                cx.emit(MeetingSummaryEvent::Cancel(*ticket));
            }
        }
        self.send_states.clear();
        self.quote = None;
        self.data = data;
        self.copied = None;
        if self.status == MeetingStatus::Summarizing {
            self.reveal.restart(cx);
        }
        self.status = MeetingStatus::Ready;
        cx.notify();
    }
    pub fn set_status(
        &mut self,
        status: MeetingStatus,
        error: impl Into<SharedString>,
        cx: &mut Context<Self>,
    ) {
        if status != MeetingStatus::Ready {
            self.send_states.retain(|_, state| {
                if let SendState::Pending(ticket) = state {
                    cx.emit(MeetingSummaryEvent::Cancel(*ticket));
                    false
                } else {
                    true
                }
            });
        }
        if status == MeetingStatus::Summarizing {
            self.loading.restart(cx);
        }
        if status != MeetingStatus::Ready {
            self.quote = None;
            self.reveal = PhaseClock::default();
        }
        self.status = status;
        self.error = error.into();
        cx.notify();
    }
    pub fn finish_send(
        &mut self,
        ticket: u64,
        result: Result<SharedString, SharedString>,
        cx: &mut Context<Self>,
    ) {
        if let Some(state) = self
            .send_states
            .values_mut()
            .find(|s| matches!(s,SendState::Pending(active) if *active==ticket))
        {
            *state = match result {
                Ok(reference) => SendState::Sent(reference),
                Err(message) => SendState::Failed(message),
            };
            cx.notify();
        }
    }
    fn send(&mut self, id: SharedString, target: SharedString, cx: &mut Context<Self>) {
        let key = (id.clone(), target.clone());
        if matches!(
            self.send_states.get(&key),
            Some(SendState::Pending(_) | SendState::Sent(_))
        ) {
            return;
        }
        self.ticket = self.ticket.wrapping_add(1);
        let ticket = self.ticket;
        self.send_states.insert(key, SendState::Pending(ticket));
        cx.emit(MeetingSummaryEvent::Send { ticket, id, target });
        cx.notify();
    }
    fn copy(&mut self, cx: &mut Context<Self>) {
        if self.copying {
            return;
        }
        self.copying = true;
        let mut text = format!("{}\n{}\n", self.data.title, self.data.meta);
        for point in &self.data.summary {
            text.push_str(&format!("\n• {}", point.text));
        }
        for point in &self.data.decisions {
            text.push_str(&format!("\n• {}", point.text));
        }
        for action in &self.data.actions {
            text.push_str(&format!(
                "\n{} {} — {}",
                if action.done { "[x]" } else { "[ ]" },
                action.point.text,
                action.owner
            ));
        }
        let write = clipboard::write(&text, cx);
        cx.spawn(async move |this, cx| {
            let ok = write.await;
            let _ = this.update(cx, |s, cx| {
                s.copying = false;
                s.copied = Some(ok);
                cx.emit(MeetingSummaryEvent::CopyResult(ok));
                cx.notify();
            });
        })
        .detach();
    }
}

fn stack() -> Div {
    div().flex().flex_col().min_w_0()
}

fn avatar(name: &str, size: f32, p: Paint) -> Div {
    let colors = [0x8468ab, 0x328b85, 0xbb7856, 0x5b78ab];
    let index = name
        .bytes()
        .fold(0usize, |sum, byte| sum + usize::from(byte))
        % colors.len();
    let color: Hsla = rgb(colors[index]).into();
    div()
        .size(px(size))
        .flex_none()
        .rounded_full()
        .border_1()
        .border_color(p.panel)
        .bg(p.panel.blend(color.opacity(0.24)))
        .text_color(p.ink)
        .text_size(px(size * 0.40))
        .flex()
        .items_center()
        .justify_center()
        .child(
            name.chars()
                .next()
                .map_or_else(String::new, |ch| ch.to_uppercase().collect()),
        )
}

impl MeetingSummary {
    fn citation(
        &self,
        point: &MeetingPoint,
        enabled: bool,
        cx: &Context<Self>,
    ) -> Option<Stateful<Div>> {
        let quote = point.quote.as_ref()?;
        let id = point.id.clone();
        let open = self.quote.as_ref() == Some(&id);
        Some(
            face(
                (ElementId::from("meeting-quote"), id.clone()),
                format!("{} · {}", quote.time, point.text),
                22.,
                5.,
                Tone::Clear,
                cx,
            )
            .flex_none()
            .px(px(5.))
            .text_size(px(11.))
            .text_color(Paint::get(cx).faint)
            .aria_expanded(open)
            .child(quote.time.clone())
            .when(!enabled, |button| {
                button.opacity(0.).tab_index(-1).cursor_default()
            })
            .when(enabled, |button| {
                button.on_click(cx.listener(move |s, _, _, cx| {
                    s.quote = (s.quote.as_ref() != Some(&id)).then(|| id.clone());
                    cx.notify();
                }))
            }),
        )
    }

    fn transcript(&self, point: &MeetingPoint, p: Paint) -> Option<Div> {
        if self.quote.as_ref() != Some(&point.id) {
            return None;
        }
        let quote = point.quote.as_ref()?;
        Some(
            stack()
                .ml(px(22.))
                .mt(px(4.))
                .py(px(7.))
                .pl(px(10.))
                .border_l_2()
                .border_color(p.line)
                .text_color(p.secondary)
                .text_size(px(12.))
                .line_height(px(18.))
                .child(
                    div()
                        .text_color(p.ink)
                        .child(format!("{} · {}", quote.speaker, quote.time)),
                )
                .child(quote.text.clone()),
        )
    }

    fn delivery(
        &self,
        item: &MeetingAction,
        target: &SharedString,
        cx: &Context<Self>,
    ) -> Stateful<Div> {
        let p = Paint::get(cx);
        let key = (item.point.id.clone(), target.clone());
        let (mark, ink, detail, blocked) = match self.send_states.get(&key) {
            Some(SendState::Pending(_)) => {
                (Glyph::Clock, p.faint, tr(cx, "Sending…", "发送中…"), true)
            }
            Some(SendState::Sent(reference)) => (Glyph::Check, p.success, reference.as_ref(), true),
            Some(SendState::Failed(message)) => (Glyph::Alert, p.danger, message.as_ref(), false),
            None => {
                let mark = if target.as_ref() == "Linear" {
                    Glyph::Slash
                } else {
                    Glyph::Book
                };
                (mark, p.secondary, target.as_ref(), false)
            }
        };
        face(
            (
                ElementId::from("meeting-send"),
                SharedString::from(format!("{}:{}", key.0, key.1)),
            ),
            format!("{} · {} · {}", target, detail, item.point.text),
            28.,
            6.,
            Tone::Clear,
            cx,
        )
        .w(px(28.))
        .flex_none()
        .when(blocked, |button| button.tab_index(-1).cursor_default())
        .child(icon(mark, 14., ink))
        .when(!blocked, |button| {
            button
                .on_click(cx.listener(move |s, _, _, cx| s.send(key.0.clone(), key.1.clone(), cx)))
        })
    }

    fn notes(&self, age: f32, cx: &Context<Self>) -> Div {
        let p = Paint::get(cx);
        let mut body = stack()
            .pt(px(16.))
            .px(px(20.))
            .pb(px(16.))
            .gap(px(16.))
            .text_size(px(13.))
            .line_height(px(19.));
        let mut offset = 0.;
        for (title, points, decision) in [
            (tr(cx, "Summary", "摘要"), &self.data.summary, false),
            (tr(cx, "Decisions", "决定"), &self.data.decisions, true),
        ] {
            if points.is_empty() || age < offset {
                continue;
            }
            let mut section = stack()
                .gap(px(6.))
                .child(div().font_weight(FontWeight::MEDIUM).child(title));
            for entry in points {
                let time = age - offset;
                offset += 0.17;
                if time < 0. {
                    break;
                }
                let mark = if decision {
                    div()
                        .size(px(14.))
                        .child(icon(Glyph::Check, 13., p.success))
                } else {
                    div()
                        .size(px(14.))
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(div().size(px(4.)).rounded_full().bg(p.faint))
                };
                section = section.child(
                    stack()
                        .opacity(ease((time / 0.14).clamp(0., 1.)))
                        .child(
                            div()
                                .flex()
                                .items_start()
                                .gap(px(8.))
                                .child(mark.mt(px(2.)).flex_none())
                                .child(div().flex_1().min_w_0().child(reveal_text(
                                    &entry.text,
                                    time,
                                    p.ink,
                                )))
                                .children(self.citation(entry, time >= 0.14, cx)),
                        )
                        .children(self.transcript(entry, p)),
                );
            }
            body = body.child(section);
            offset += 0.08;
            if age < offset {
                return body;
            }
        }
        if !self.data.actions.is_empty() && age >= offset {
            let done = self.data.actions.iter().filter(|item| item.done).count();
            let mut actions = stack().child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .pb(px(6.))
                    .child(div().font_weight(FontWeight::MEDIUM).child(tr(
                        cx,
                        "Action items",
                        "行动事项",
                    )))
                    .child(
                        div()
                            .text_size(px(11.))
                            .text_color(p.faint)
                            .child(format!("{done}/{}", self.data.actions.len())),
                    ),
            );
            for item in &self.data.actions {
                let time = age - offset;
                offset += 0.17;
                if time < 0. {
                    break;
                }
                let id = item.point.id.clone();
                let ink = if item.done { p.secondary } else { p.ink };
                let check = face(
                    (ElementId::from("meeting-check"), id.clone()),
                    item.point.text.clone(),
                    16.,
                    4.,
                    Tone::Clear,
                    cx,
                )
                .w(px(16.))
                .flex_none()
                .role(Role::CheckBox)
                .aria_toggled(item.done.into())
                .border_1()
                .border_color(if item.done { p.bright } else { p.line })
                .when(item.done, |box_| {
                    box_.bg(p.bright).child(icon(Glyph::Check, 12., p.inverse))
                })
                .on_click(cx.listener(move |s, _, _, cx| {
                    if let Some(item) = s.data.actions.iter_mut().find(|item| item.point.id == id) {
                        item.done = !item.done;
                        cx.emit(MeetingSummaryEvent::ActionChanged {
                            id: id.clone(),
                            done: item.done,
                        });
                        cx.notify();
                    }
                }));
                let meta = div()
                    .flex()
                    .flex_wrap()
                    .items_center()
                    .gap(px(6.))
                    .text_size(px(11.))
                    .text_color(p.faint)
                    .child(avatar(&item.owner, 17., p))
                    .child(item.owner.clone())
                    .when(!item.due.is_empty(), |row| {
                        row.child("·").child(item.due.clone())
                    })
                    .children(self.citation(&item.point, time >= 0.14, cx));
                actions = actions.child(
                    stack()
                        .py(px(7.))
                        .border_t_1()
                        .border_color(p.line)
                        .opacity(ease((time / 0.14).clamp(0., 1.)))
                        .child(
                            div()
                                .flex()
                                .items_start()
                                .gap(px(8.))
                                .child(
                                    div()
                                        .size(px(16.))
                                        .flex_none()
                                        .mt(px(2.))
                                        .when(time >= 0.14, |slot| slot.child(check)),
                                )
                                .child(
                                    stack()
                                        .flex_1()
                                        .gap(px(3.))
                                        .text_color(ink)
                                        .child(reveal_text(&item.point.text, time, ink))
                                        .child(meta),
                                )
                                .child(
                                    div()
                                        .flex()
                                        .flex_wrap()
                                        .justify_end()
                                        .flex_none()
                                        .gap(px(2.))
                                        .min_w(px(
                                            (self.targets.len().min(2) as f32 * 30. - 2.).max(0.)
                                        ))
                                        .max_w(relative(0.34))
                                        .when(time >= 0.14, |row| {
                                            row.children(
                                                self.targets
                                                    .iter()
                                                    .map(|target| self.delivery(item, target, cx)),
                                            )
                                        }),
                                ),
                        )
                        .children(self.transcript(&item.point, p)),
                );
            }
            body = body.child(actions);
        }
        body
    }
}

fn reveal_text(text: &SharedString, age: f32, ink: Hsla) -> StyledText {
    if age >= 0.24 {
        return StyledText::new(text.clone());
    }
    let count = text.chars().count();
    let mut starts = [text.len(); 6];
    starts[0] = 0;
    let mut part = 1;
    for (index, (byte, _)) in text.char_indices().enumerate() {
        while part < 5 && index >= count * part / 5 {
            starts[part] = byte;
            part += 1;
        }
    }
    let highlights = starts
        .windows(2)
        .enumerate()
        .filter(|(_, bytes)| bytes[0] < bytes[1])
        .map(|(index, bytes)| {
            let delay = index as f32 * 0.032;
            let opacity = ease(((age - delay) / 0.11).clamp(0., 1.));
            (
                bytes[0]..bytes[1],
                HighlightStyle {
                    color: Some(ink.opacity(opacity)),
                    ..Default::default()
                },
            )
        });
    StyledText::new(text.clone()).with_highlights(highlights)
}

impl Render for MeetingSummary {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let ready = self.status == MeetingStatus::Ready;
        let mut people = div().flex().items_center().flex_none();
        for (index, name) in self.data.attendees.iter().take(4).enumerate() {
            people = people.child(avatar(name, 25., p).when(index > 0, |node| node.ml(px(-6.))));
        }
        let extra = self.data.attendees.len().saturating_sub(4);
        if extra > 0 {
            people = people.child(
                div()
                    .ml(px(-4.))
                    .size(px(25.))
                    .rounded_full()
                    .border_1()
                    .border_color(p.panel)
                    .bg(p.tray)
                    .flex()
                    .items_center()
                    .justify_center()
                    .text_size(px(10.))
                    .child(format!("+{extra}")),
            );
        }
        let label = tr(cx, "Regenerate", "重新生成");
        let regenerate = face("meeting-regenerate", label, 30., 6., Tone::Clear, cx)
            .w(px(30.))
            .child(icon(Glyph::Redo, 15., p.secondary))
            .on_click(cx.listener(|_, _, _, cx| cx.emit(MeetingSummaryEvent::Regenerate)));
        let copy_label = match self.copied {
            Some(true) => tr(cx, "Copied", "已复制"),
            Some(false) => tr(cx, "Copy failed — retry", "复制失败，重试"),
            None => tr(cx, "Copy notes", "复制纪要"),
        };
        let copy = face("meeting-copy", copy_label, 30., 6., Tone::Clear, cx)
            .w(px(30.))
            .when(!ready || self.copying, |button| {
                button.tab_index(-1).cursor_default()
            })
            .child(icon(
                match self.copied {
                    Some(true) => Glyph::Check,
                    Some(false) => Glyph::Alert,
                    None => Glyph::Copy,
                },
                15.,
                p.secondary,
            ))
            .when(ready, |button| {
                button.on_click(cx.listener(|s, _, _, cx| s.copy(cx)))
            });
        let body = match self.status {
            MeetingStatus::Ready => {
                let count =
                    self.data.summary.len() + self.data.decisions.len() + self.data.actions.len();
                let age = self.reveal.time(count as f32 * 0.17 + 0.40, w, cx);
                self.notes(age, cx)
            }
            MeetingStatus::Summarizing => {
                let age = self.loading.time(1.5, w, cx);
                stack()
                    .min_h(px(102.))
                    .py(px(15.))
                    .px(px(20.))
                    .gap(px(10.))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(8.))
                            .text_size(px(13.))
                            .text_color(p.secondary)
                            .child(transformed(
                                Glyph::Spinner,
                                14.,
                                p.secondary,
                                age * 340.,
                                1.,
                                (0., 0.),
                                1.,
                            ))
                            .child(tr(cx, "Summarizing transcript…", "正在整理会议记录…")),
                    )
                    .children([0.80, 0.59].into_iter().enumerate().map(|(i, width)| {
                        let x = ((age * 3. - i as f32 * 0.42).cos() + 1.) / 2.;
                        div()
                            .w(relative(width))
                            .h(px(7.))
                            .rounded(px(4.))
                            .bg(p.line.opacity(0.42 + x * 0.50))
                    }))
            }
            MeetingStatus::Error => stack()
                .min_h(px(102.))
                .p(px(20.))
                .justify_center()
                .text_size(px(13.))
                .line_height(px(20.))
                .text_color(p.danger)
                .child(
                    div()
                        .id("meeting-error")
                        .role(Role::Alert)
                        .child(self.error.clone()),
                ),
            MeetingStatus::NoTranscript => stack()
                .min_h(px(102.))
                .p(px(20.))
                .justify_center()
                .text_size(px(13.))
                .text_color(p.secondary)
                .child(tr(
                    cx,
                    "No transcript is available for this meeting.",
                    "这场会议没有转录记录。",
                )),
        };
        let measured = self.measured_body.clone();
        let height = measured.get();
        if self.body_height.value(cx) == 0. {
            self.body_height.reset(f32::from(height));
        } else {
            self.body_height.duration(f32::from(height), 0.24, cx);
        }
        let current = self.body_height.get(w, cx).max(0.);
        div()
            .id("meeting-summary")
            .role(Role::Group)
            .aria_label(self.data.title.clone())
            .w_full()
            .max_w(px(640.))
            .rounded(crate::foundation::surface_radius(cx))
            .border_1()
            .border_color(p.line)
            .bg(p.panel)
            .text_color(p.ink)
            .flex()
            .flex_col()
            .on_key_down(cx.listener(|s, e: &KeyDownEvent, _, cx| {
                if e.keystroke.key == "escape" && s.quote.take().is_some() {
                    cx.notify();
                    cx.stop_propagation();
                }
            }))
            .child(
                div()
                    .flex()
                    .flex_wrap()
                    .items_center()
                    .justify_between()
                    .gap(px(8.))
                    .pt(px(18.))
                    .px(px(20.))
                    .pb(px(16.))
                    .border_b_1()
                    .border_color(p.line)
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(10.))
                            .flex_1()
                            .min_w(px(160.))
                            .child(brand_mark(&self.service, 20., cx).unwrap_or_else(|| {
                                icon(Glyph::Monitor, 20., p.secondary).into_any_element()
                            }))
                            .child(
                                stack()
                                    .gap(px(2.))
                                    .child(
                                        div()
                                            .text_size(px(15.))
                                            .line_height(px(22.))
                                            .font_weight(FontWeight::MEDIUM)
                                            .child(self.data.title.clone()),
                                    )
                                    .child(
                                        div()
                                            .text_size(px(12.))
                                            .line_height(px(18.))
                                            .text_color(p.secondary)
                                            .child(self.data.meta.clone()),
                                    ),
                            ),
                    )
                    .child(people),
            )
            .child(
                div()
                    .w_full()
                    .overflow_hidden()
                    .when(height > px(0.), |view| view.h(px(current)))
                    .flex()
                    .flex_col()
                    .on_children_prepainted(move |bounds, w, _| {
                        if let Some(bounds) = bounds.first()
                            && bounds.size.height != measured.get()
                        {
                            measured.set(bounds.size.height);
                            w.request_animation_frame();
                        }
                    })
                    .child(body.flex_none()),
            )
            .child(
                div()
                    .min_h(px(53.))
                    .flex()
                    .flex_wrap()
                    .items_center()
                    .justify_between()
                    .gap(px(4.))
                    .pl(px(20.))
                    .pr(px(12.))
                    .py(px(6.))
                    .border_t_1()
                    .border_color(p.line)
                    .child(
                        div()
                            .flex()
                            .flex_wrap()
                            .gap(px(6.))
                            .text_size(px(11.))
                            .text_color(p.faint)
                            .child(self.credit.clone())
                            .when_some(self.transcript_words, |row, words| {
                                row.child(format!("· {words} {}", tr(cx, "words", "词")))
                            }),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(4.))
                            .child(copy)
                            .when(self.status != MeetingStatus::Summarizing, |row| {
                                row.child(regenerate)
                            }),
                    ),
            )
    }
}

//! Confirm a clipboard write on the active platform.
use gpui::{App, Task};
#[cfg(target_family = "wasm")]
#[wasm_bindgen::prelude::wasm_bindgen(
    inline_js = "export function kuiCopy(s){return navigator.clipboard ? navigator.clipboard.writeText(s) : Promise.reject(new Error('Clipboard unavailable'))}"
)]
extern "C" {
    #[wasm_bindgen::prelude::wasm_bindgen(js_name=kuiCopy,catch)]
    fn write_web(s: &str) -> Result<js_sys::Promise, wasm_bindgen::JsValue>;
}
pub fn write(text: &str, cx: &mut App) -> Task<bool> {
    #[cfg(not(target_family = "wasm"))]
    {
        cx.write_to_clipboard(gpui::ClipboardItem::new_string(text.to_owned()));
        Task::ready(
            cx.read_from_clipboard()
                .and_then(|v| v.text())
                .is_some_and(|v| v == text),
        )
    }
    #[cfg(target_family = "wasm")]
    {
        let request = write_web(text);
        cx.spawn(async move |_| match request {
            Ok(p) => wasm_bindgen_futures::JsFuture::from(p).await.is_ok(),
            Err(_) => false,
        })
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

